function check(input, actual, expected) {
  const [cars, directions, arrivalTimes] = input;
  if (!Array.isArray(actual)) return false;
  const info = new Map(cars.map((id, i) => [id, { direction: directions[i], time: arrivalTimes[i] }]));
  const passed = new Set();
  let green = 'A', lastTime = -1;
  for (const line of actual) {
    if (typeof line !== 'string') return false;
    const light = /^Traffic Light On Road (A|B) Is Green$/.exec(line);
    if (light) {
      // Turning a road green that is already green is a wrong answer.
      if (light[1] === green) return false;
      green = light[1];
      continue;
    }
    const pass = /^Car (\d+) Has Passed Road (A|B) In Direction (\d)$/.exec(line);
    if (!pass) return false;
    const id = Number(pass[1]), car = info.get(id), road = Number(pass[3]) <= 2 ? 'A' : 'B';
    if (!car || passed.has(id) || car.direction !== Number(pass[3]) || pass[2] !== road || road !== green) return false;
    // Cars cross in order of arrival; cars that arrive together may cross in any order.
    if (car.time < lastTime) return false;
    lastTime = car.time;
    passed.add(id);
  }
  return passed.size === cars.length;
}

