function validate(input) {
  const [cars, directions, arrivalTimes] = input;
  if (!Array.isArray(cars) || cars.length < 1 || cars.length > 20) return 'Give 1 to 20 cars.';
  if (!Array.isArray(directions) || directions.length !== cars.length) return 'directions needs one direction per car.';
  if (!Array.isArray(arrivalTimes) || arrivalTimes.length !== cars.length) return 'arrivalTimes needs one time per car.';
  if (!cars.every((id) => Number.isInteger(id) && id >= 1 && id <= 1000)) return 'Each car id is an integer from 1 to 1000.';
  if (new Set(cars).size !== cars.length) return 'Car ids must be distinct.';
  if (!directions.every((d) => Number.isInteger(d) && d >= 1 && d <= 4)) return 'Each direction is 1, 2, 3 or 4.';
  for (let i = 0; i < arrivalTimes.length; i++) {
    const time = arrivalTimes[i];
    if (!Number.isInteger(time) || time < 0 || time > 1000) return 'Each arrival time is an integer from 0 to 1000 ms.';
    if (i > 0 && time < arrivalTimes[i - 1]) return 'List arrivalTimes in non-decreasing order.';
  }
  return null;
}

