function adapt(input, solve, kit) {
  const [cars, directions, arrivalTimes] = input, start = Date.now();
  const light = new solve();
  if (!light || typeof light.carArrived !== 'function') throw new Error('TrafficLight needs a method carArrived.');
  const printed = [], inside = new Set(), crossed = new Set();
  let green = 'A', failure = null;
  const fail = (message) => { failure = failure ?? message; };
  cars.forEach((carId, i) => {
    const direction = directions[i], roadId = direction <= 2 ? 1 : 2, road = roadId === 1 ? 'A' : 'B';
    const turnGreen = () => {
      if (green === road) fail(`Car ${carId} turned road ${road} green, but it was green already.`);
      else if (inside.size) fail(`The light turned green on road ${road} while car ${[...inside][0]} was still in the intersection.`);
      green = road;
      printed.push(`Traffic Light On Road ${road} Is Green`);
      kit.trace(`The light turns green on road ${road}`);
    };
    const crossCar = () => {
      const now = Date.now() - start;
      if (crossed.has(carId)) fail(`Car ${carId} crossed twice.`);
      else if (green !== road) fail(`Car ${carId} entered the intersection while road ${road} was red.`);
      else if (now !== arrivalTimes[i]) fail(`Car ${carId} arrived at ${arrivalTimes[i]} ms but crossed only at ${now} ms.`);
      crossed.add(carId);
      inside.add(carId);
      printed.push(`Car ${carId} Has Passed Road ${road} In Direction ${direction}`);
      kit.trace(`Car ${carId} enters the intersection on road ${road}`);
      // The car leaves on a later tick of the same millisecond.
      return new Promise((resolve) => setTimeout(() => {
        inside.delete(carId);
        kit.trace(`Car ${carId} has left the intersection`);
        resolve();
      }, 0));
    };
    setTimeout(() => {
      kit.trace(`Car ${carId} arrives on road ${road}, direction ${direction}`);
      const result = light.carArrived(carId, roadId, direction, turnGreen, crossCar);
      if (result && typeof result.then === 'function') result.then(null, (error) => fail(`carArrived failed for car ${carId}: ${error && error.message || error}`));
    }, arrivalTimes[i]);
  });
  // A correct solution has let every car through by the last arrival; the extra time shows late crossings.
  return new Promise((resolve, reject) => setTimeout(() => {
    const stuck = cars.find((id) => !crossed.has(id));
    if (stuck !== undefined) fail(`Car ${stuck} never crossed.`);
    if (failure) reject(new Error(failure));
    else resolve(printed);
  }, Math.max(...arrivalTimes) + 50));
}

