class TrafficLight {
  constructor() {
    this.greenRoad = 1;
    this.lastTurn = Promise.resolve();
  }

  carArrived(carId, roadId, direction, turnGreen, crossCar) {
    const turn = this.lastTurn.then(async () => {
      if (this.greenRoad !== roadId) {
        turnGreen();
        this.greenRoad = roadId;
      }
      await crossCar();
    });
    this.lastTurn = turn;
    return turn;
  }
}

