class TrafficLight {
  constructor() {
    this.green = 1;
    this.busy = false;
    this.waiting = [];
  }

  carArrived(carId, roadId, direction, turnGreen, crossCar) {
    return new Promise((done) => {
      this.waiting.push({ roadId, turnGreen, crossCar, done });
      this.serve();
    });
  }

  // While the intersection is free, let the car that has waited longest through.
  serve() {
    if (this.busy || this.waiting.length === 0) return;
    const car = this.waiting.shift();
    this.busy = true;
    if (car.roadId !== this.green) {
      car.turnGreen();
      this.green = car.roadId;
    }
    car.crossCar().then(() => {
      this.busy = false;
      car.done();
      this.serve();
    });
  }
}

