function generate(rand, size) {
  const n = size === 'small' ? 1 + Math.floor(rand() * 6) : 20;
  const pool = Array.from({ length: size === 'small' ? 9 : 1000 }, (_, i) => i + 1), cars = [];
  for (let i = 0; i < n; i++) {
    const j = i + Math.floor(rand() * (pool.length - i));
    [pool[i], pool[j]] = [pool[j], pool[i]];
    cars.push(pool[i]);
  }
  const directions = cars.map(() => 1 + Math.floor(rand() * 4));
  // Many cars share an arrival time, so cars of both roads often meet at the intersection.
  const arrivalTimes = [];
  let time = Math.floor(rand() * 20);
  for (let i = 0; i < n; i++) {
    if (i > 0 && rand() < 0.5) time += Math.floor(rand() * (size === 'small' ? 15 : 100));
    arrivalTimes.push(Math.min(time, 1000));
  }
  return [cars, directions, arrivalTimes];
}
